package io.tenvyr.control.engine;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.*;
import java.time.Instant;
import java.util.*;
import static io.tenvyr.control.engine.EngineFacts.*;

/** Supervision projects deterministic synthetic results through the same inbox terminal authority. */
public final class SupervisionService {
  public record Expectation(boolean expected,int startupGraceMs,int staleAfterMs){}
  private final Db db;private final ResultInboxService inbox;private final EngineService engine;private final Map<String,Expectation> expected;private String cursor;
  public SupervisionService(Db db,ResultInboxService inbox,EngineService engine,Map<String,String> env){this.db=db;this.inbox=inbox;this.engine=engine;expected=parse(env.get("ORCHESTRATOR_SUPERVISION_CONFIG"));}
  public static Map<String,Expectation> parse(String raw){Map<String,Expectation> out=new LinkedHashMap<>();if(raw==null||raw.isEmpty())return out;ObjectNode n=Json.requireObject(Json.parse(raw),"ORCHESTRATOR_SUPERVISION_CONFIG");for(String agent:Json.keys(n)){JsonNode heartbeat=Json.requireObject(n.path(agent).get("heartbeat"),"heartbeat");if(!heartbeat.path("expected").isBoolean())throw new IllegalArgumentException("heartbeat.expected must be boolean");Expectation expectation=new Expectation(heartbeat.path("expected").asBoolean(),duration(heartbeat.get("startupGraceMs")),duration(heartbeat.get("staleAfterMs")));out.put(agent,expectation);}return out;}
  private static int duration(JsonNode n){if(n==null||!n.isIntegralNumber()||!n.canConvertToInt()||n.intValue()<1||n.intValue()>86400000)throw new IllegalArgumentException("Heartbeat duration must be 1..86400000 ms");return n.intValue();}
  public void evaluate(Instant now){List<String> agents=expected.entrySet().stream().filter(e->e.getValue().expected()).map(Map.Entry::getKey).toList();if(agents.isEmpty())return;String sql="SELECT * FROM step_attempts a WHERE status IN ('DISPATCHED','RUNNING') AND \"dispatchedAt\" IS NOT NULL AND \"executorSnapshot\"->>'agent' IN ("+String.join(",",Collections.nCopies(agents.size(),"?"))+")";List<Object> args=new ArrayList<>(agents);if(cursor!=null){sql+=" AND (a.\"dispatchedAt\" > (SELECT c.\"dispatchedAt\" FROM step_attempts c WHERE c.id=?) OR (a.\"dispatchedAt\" = (SELECT c.\"dispatchedAt\" FROM step_attempts c WHERE c.id=?) AND a.id>?))";args.add(cursor);args.add(cursor);args.add(cursor);}sql+=" ORDER BY a.\"dispatchedAt\",a.id LIMIT 100";List<ObjectNode> rows=db.query(sql,args.toArray());cursor=rows.size()<100?null:rows.get(rows.size()-1).path("id").asText();for(ObjectNode row:rows){try{ObjectNode result=syntheticResult(row,expected,now);if(result==null)continue;ResultInboxService.Application applied=inbox.apply(result,Json.object("adapter","supervision","receivedAt",Protocol.jsInstant(now)));if(applied.disposition().equals("applied")||applied.disposition().equals("duplicate"))engine.reconcileExecution(applied.executionId(),true);}catch(Exception error){System.err.println("Deferred supervision candidate: "+row.path("id").asText());}}}
  public static ObjectNode syntheticResult(ObjectNode attempt,Map<String,Expectation> expected,Instant now){String agent=attempt.path("executorSnapshot").path("agent").asText();Expectation expectation=expected.get(agent);if(expectation==null||!expectation.expected())return null;String status=attempt.path("status").asText();Instant dispatched=instant(attempt,"dispatchedAt"),baseline=instant(attempt,"lastHeartbeatReceivedAt");if(status.equals("DISPATCHED")&&!attempt.hasNonNull("lastEventReceivedAt")&&dispatched!=null&&!dispatched.plusMillis(expectation.startupGraceMs()).isAfter(now))return synthetic(attempt,"AGENT_ACCEPTANCE_TIMEOUT","Agent \""+agent+"\" did not emit an event within "+expectation.startupGraceMs()+"ms of dispatch",dispatched.plusMillis(expectation.startupGraceMs()));if(status.equals("RUNNING")){boolean never=baseline==null;if(baseline==null)baseline=instant(attempt,"startTime");if(baseline!=null&&!baseline.plusMillis(expectation.staleAfterMs()).isAfter(now))return synthetic(attempt,"AGENT_HEARTBEAT_STALE",never?"Agent \""+agent+"\" never heartbeated; no heartbeat within "+expectation.staleAfterMs()+"ms of start":"Agent \""+agent+"\" heartbeat stale for more than "+expectation.staleAfterMs()+"ms",baseline.plusMillis(expectation.staleAfterMs()));}return null;}
  static ObjectNode synthetic(ObjectNode attempt,String code,String message,Instant completed){return Json.object("schemaVersion","1","invocationId",attempt.path("invocationId"),"executionId",attempt.path("executionId"),"stepExecutionId",attempt.path("logicalStepId"),"status","timed_out","error",Json.object("code",code,"message",message,"retryable",true),"completedAt",Protocol.jsInstant(completed));}
}
